import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { motion } from 'framer-motion';
import { Truck, Building2, User, Phone, Mail, MapPin, Car, FileText, Lock } from 'lucide-react';
import toast from 'react-hot-toast';
import api from '../../services/api';
import ValidatedInput from '../../components/forms/ValidatedInput';
import PasswordStrength from '../../components/forms/PasswordStrength';

const registerSchema = z.object({
    companyName: z.string().min(2, 'Company name is required'),
    contactPerson: z.string().min(2, 'Contact person is required'),
    contactPhone: z.string().min(10, 'Valid phone number is required'),
    email: z.string().email('Valid email is required'),
    password: z.string().min(8, 'Password must be at least 8 characters')
        .regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/, 'Password must contain uppercase, lowercase, and number'),
    address: z.string().min(5, 'Address is required'),
    city: z.string().min(2, 'City is required'),
    state: z.string().min(2, 'State is required'),
    vehicleType: z.string().optional(),
    licenseNumber: z.string().optional()
});

const RegisterPage = () => {
    const [isLoading, setIsLoading] = useState(false);
    const navigate = useNavigate();

    const { register, handleSubmit, watch, formState: { errors } } = useForm({
        resolver: zodResolver(registerSchema)
    });

    const watchPassword = watch('password');

    const onSubmit = async (data) => {
        setIsLoading(true);
        try {
            await api.post('/dispatch/register', data);
            toast.success('Registration successful! Please wait for account verification.');
            navigate('/login');
        } catch (error) {
            toast.error(error.response?.data?.message || 'Registration failed');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-teal-50 via-white to-indigo-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 py-12 px-4">
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="max-w-2xl mx-auto"
            >
                <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-8">
                    {/* Header */}
                    <div className="text-center mb-8">
                        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-teal-100 dark:bg-teal-900/30 mb-4">
                            <Truck className="w-8 h-8 text-teal-600 dark:text-teal-400" />
                        </div>
                        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
                            Register as Dispatch Partner
                        </h1>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">
                            Join our delivery network
                        </p>
                    </div>

                    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                        {/* Company Information */}
                        <div className="space-y-4">
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                <Building2 className="h-5 w-5 text-teal-600" />
                                Company Information
                            </h3>

                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <ValidatedInput
                                    label="Company Name"
                                    name="companyName"
                                    required
                                    error={errors.companyName?.message}
                                    {...register('companyName')}
                                />
                                <ValidatedInput
                                    label="Contact Person"
                                    name="contactPerson"
                                    icon={User}
                                    required
                                    error={errors.contactPerson?.message}
                                    {...register('contactPerson')}
                                />
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <ValidatedInput
                                    label="Contact Phone"
                                    name="contactPhone"
                                    icon={Phone}
                                    type="tel"
                                    required
                                    error={errors.contactPhone?.message}
                                    {...register('contactPhone')}
                                />
                                <ValidatedInput
                                    label="Email Address"
                                    name="email"
                                    icon={Mail}
                                    type="email"
                                    required
                                    error={errors.email?.message}
                                    {...register('email')}
                                />
                            </div>
                        </div>

                        {/* Account Security */}
                        <div className="space-y-4">
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                <Lock className="h-5 w-5 text-teal-600" />
                                Account Security
                            </h3>

                            <ValidatedInput
                                label="Password"
                                name="password"
                                type="password"
                                required
                                error={errors.password?.message}
                                {...register('password')}
                            />
                            <PasswordStrength password={watchPassword || ''} />
                        </div>

                        {/* Location */}
                        <div className="space-y-4">
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                <MapPin className="h-5 w-5 text-teal-600" />
                                Location
                            </h3>

                            <ValidatedInput
                                label="Address"
                                name="address"
                                required
                                error={errors.address?.message}
                                {...register('address')}
                            />

                            <div className="grid grid-cols-2 gap-4">
                                <ValidatedInput
                                    label="City"
                                    name="city"
                                    required
                                    error={errors.city?.message}
                                    {...register('city')}
                                />
                                <ValidatedInput
                                    label="State"
                                    name="state"
                                    required
                                    error={errors.state?.message}
                                    {...register('state')}
                                />
                            </div>
                        </div>

                        {/* Vehicle Information */}
                        <div className="space-y-4">
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                <Car className="h-5 w-5 text-teal-600" />
                                Vehicle Information (Optional)
                            </h3>

                            <div className="grid grid-cols-2 gap-4">
                                <ValidatedInput
                                    label="Vehicle Type"
                                    name="vehicleType"
                                    placeholder="e.g., Motorcycle, Van"
                                    error={errors.vehicleType?.message}
                                    {...register('vehicleType')}
                                />
                                <ValidatedInput
                                    label="License Number"
                                    name="licenseNumber"
                                    icon={FileText}
                                    error={errors.licenseNumber?.message}
                                    {...register('licenseNumber')}
                                />
                            </div>
                        </div>

                        <button
                            type="submit"
                            disabled={isLoading}
                            className="w-full flex items-center justify-center gap-2 px-6 py-3 bg-teal-600 hover:bg-teal-700 text-white rounded-xl font-medium transition-colors disabled:opacity-50"
                        >
                            {isLoading ? (
                                <>
                                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                    Registering...
                                </>
                            ) : (
                                <>
                                    <Truck className="h-5 w-5" />
                                    Register as Dispatch Partner
                                </>
                            )}
                        </button>
                    </form>
                </div>
            </motion.div>
        </div>
    );
};

export default RegisterPage;
